// Step 1: Define the abstraction
public interface IReportGenerator
{
    Task<byte[]> GenerateSalesReportAsync(ReportRequest request, CancellationToken ct);
}

// Step 2: Keep the legacy implementation
public class LegacyReportGenerator : IReportGenerator
{
    public async Task<byte[]> GenerateSalesReportAsync(ReportRequest request, CancellationToken ct)
    {
        // Existing complex logic with Crystal Reports
        return await _legacyEngine.GenerateAsync(request);
    }
}

// Step 3: Build the new implementation
public class ModernReportGenerator : IReportGenerator
{
    public async Task<byte[]> GenerateSalesReportAsync(ReportRequest request, CancellationToken ct)
    {
        var data = await _repository.GetSalesDataAsync(request.DateRange, ct);
        return await _pdfRenderer.RenderAsync(data, ct);
    }
}

// Step 4: Register both in DI and switch via configuration
builder.Services.AddKeyedSingleton<IReportGenerator, LegacyReportGenerator>("legacy");
builder.Services.AddKeyedSingleton<IReportGenerator, ModernReportGenerator>("modern");

// Step 5: Resolve based on a feature flag
public class ReportController : ControllerBase
{
    private readonly IReportGenerator _generator;

    public ReportController([FromKeyedServices("modern")] IReportGenerator modernGenerator, IFeatureManager features)
    {
        _generator = features.IsEnabledAsync("UseModernReports").Result
            ? modernGenerator
            : new LegacyReportGenerator(); // Or inject by key
    }
}
